const dist = Number(api.args?.distance ?? api.args?.dist ?? api.args?.range ?? 25);
const start = api.pos();

try {
  await api.wander(dist);
} catch (e) {}

const dest = api.pos();
const blocks = api.blocksAround(24);
let found = [];
if (blocks["water"]) found.push("water");
if (blocks["oak_log"] || blocks["birch_log"] || blocks["spruce_log"]) found.push("trees");
if (blocks["coal_ore"] || blocks["iron_ore"] || blocks["copper_ore"]) found.push("ores");

const ents = api.entities({maxDist: 24});
if (ents.some(e => e.name === "villager")) found.push("village");

api.say(`Explored near ${Math.round(dest.x)}, ${Math.round(dest.z)}. Found: ${found.length > 0 ? found.join(", ") : "nothing special"}`);

try {
  await api.goto(start.x, start.y, start.z, 3);
} catch (e) {}

return `Exploration complete: found ${found.join(", ") || "none"}`;

