const start = api.pos();
const angle = Math.random() * Math.PI * 2;
const targetX = start.x + Math.cos(angle) * 60;
const targetZ = start.z + Math.sin(angle) * 60;

try {
    await api.goto(targetX, start.y, targetZ, 15);
} catch(e) {
    // If pathfinding fails, just explore where we managed to reach
}

